insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('deu-22-30','deu','신명기',22,30,'사람이 그의 아버지의 아내를 취하여 아버지의 하체를 드러내지 말지니라',5501),
('deu-23-1','deu','신명기',23,1,'고환이 상한 자나 음경이 잘린 자는 여호와의 총회에 들어오지 못하리라',5502),
('deu-23-2','deu','신명기',23,2,'사생자는 여호와의 총회에 들어오지 못하리니 십 대에 이르기까지도 여호와의 총회에 들어오지 못하리라',5503),
('deu-23-3','deu','신명기',23,3,'암몬 사람과 모압 사람은 여호와의 총회에 들어오지 못하리니 그들에게 속한 자는 십 대뿐 아니라 영원히 여호와의 총회에 들어오지 못하리라',5504),
('deu-23-4','deu','신명기',23,4,'그들은 너희가 애굽에서 나올 때에 떡과 물로 너희를 길에서 영접하지 아니하고 메소보다미아의 브돌 사람 브올의 아들 발람에게 뇌물을 주어 너희를 저주하게 하려 하였으나',5505),
('deu-23-5','deu','신명기',23,5,'네 하나님 여호와께서 너를 사랑하시므로 네 하나님 여호와께서 발람의 말을 듣지 아니하시고 네 하나님 여호와께서 그 저주를 변하여 복이 되게 하셨나니',5506),
('deu-23-6','deu','신명기',23,6,'네 평생에 그들의 평안함과 형통함을 영원히 구하지 말지니라',5507),
('deu-23-7','deu','신명기',23,7,'너는 에돔 사람을 미워하지 말라 그는 네 형제임이니라 애굽 사람을 미워하지 말라 네가 그의 땅에서 객이 되었음이니라',5508),
('deu-23-8','deu','신명기',23,8,'그들의 삼 대 후 자손은 여호와의 총회에 들어올 수 있느니라',5509),
('deu-23-9','deu','신명기',23,9,'네가 적군을 치러 출진할 때에 모든 악한 일을 스스로 삼갈지니',5510),
('deu-23-10','deu','신명기',23,10,'너희 중에 누가 밤에 몽설함으로 부정하거든 진영 밖으로 나가고 진영 안에 들어오지 아니하다가',5511),
('deu-23-11','deu','신명기',23,11,'해 질 때에 목욕하고 해 진 후에 진에 들어올 것이요',5512),
('deu-23-12','deu','신명기',23,12,'네 진영 밖에 변소를 마련하고 그리로 나가되',5513),
('deu-23-13','deu','신명기',23,13,'네 기구에 작은 삽을 더하여 밖에 나가서 대변을 볼 때에 그것으로 땅을 팔 것이요 몸을 돌려 그 배설물을 덮을지니',5514),
('deu-23-14','deu','신명기',23,14,'이는 네 하나님 여호와께서 너를 구원하시고 적군을 네게 넘기시려고 네 진영 중에 행하심이라 그러므로 네 진영을 거룩히 하라 그리하면 네게서 불결한 것을 보시지 않으므로 너를 떠나지 아니하시리라',5515),
('deu-23-15','deu','신명기',23,15,'종이 그의 주인을 피하여 네게로 도망하거든 너는 그의 주인에게 돌려주지 말고',5516),
('deu-23-16','deu','신명기',23,16,'그가 네 성읍 중에서 원하는 곳을 택하는 대로 너와 함께 네 가운데에 거주하게 하고 그를 압제하지 말지니라',5517),
('deu-23-17','deu','신명기',23,17,'이스라엘 여자 중에 창기가 있지 못할 것이요 이스라엘 남자 중에 남창이 있지 못할지니',5518),
('deu-23-18','deu','신명기',23,18,'창기가 번 돈과 개 같은 자의 소득은 어떤 서원하는 일로든지 네 하나님 여호와의 전에 가져오지 말라 이 둘은 다 네 하나님 여호와께 가증한 것임이니라',5519),
('deu-23-19','deu','신명기',23,19,'네가 형제에게 꾸어주거든 이자를 받지 말지니 곧 돈의 이자, 식물의 이자, 이자를 낼 만한 모든 것의 이자를 받지 말 것이라',5520),
('deu-23-20','deu','신명기',23,20,'타국인에게 네가 꾸어주면 이자를 받아도 되거니와 네 형제에게 꾸어주거든 이자를 받지 말라 그리하면 네 하나님 여호와께서 네가 들어가서 차지할 땅에서 네 손으로 하는 범사에 복을 내리시리라',5521),
('deu-23-21','deu','신명기',23,21,'네 하나님 여호와께 서원하거든 갚기를 더디하지 말라 네 하나님 여호와께서 반드시 그것을 네게 요구하시리니 더디면 그것이 네게 죄가 될 것이라',5522),
('deu-23-22','deu','신명기',23,22,'네가 서원하지 아니하였으면 무죄하리라 그러나',5523),
('deu-23-23','deu','신명기',23,23,'네 입으로 말한 것은 그대로 실행하도록 유의하라 무릇 자원한 예물은 네 하나님 여호와께 네가 서원하여 입으로 언약한 대로 행할지니라',5524),
('deu-23-24','deu','신명기',23,24,'네 이웃의 포도원에 들어갈 때에는 마음대로 그 포도를 배불리 먹어도 되느니라 그러나 그릇에 담지는 말 것이요',5525),
('deu-23-25','deu','신명기',23,25,'네 이웃의 곡식밭에 들어갈 때에는 네가 손으로 그 이삭을 따도 되느니라 그러나 네 이웃의 곡식밭에 낫을 대지는 말지니라',5526),
('deu-24-1','deu','신명기',24,1,'사람이 아내를 맞이하여 데려온 후에 그에게 수치되는 일이 있음을 발견하고 그를 기뻐하지 아니하면 이혼 증서를 써서 그의 손에 주고 그를 자기 집에서 내보낼 것이요',5527),
('deu-24-2','deu','신명기',24,2,'그 여자는 그의 집에서 나가서 다른 사람의 아내가 되려니와',5528),
('deu-24-3','deu','신명기',24,3,'그의 둘째 남편도 그를 미워하여 이혼 증서를 써서 그의 손에 주고 그를 자기 집에서 내보냈거나 또는 그를 아내로 맞이한 둘째 남편이 죽었다 하자',5529),
('deu-24-4','deu','신명기',24,4,'그 여자는 이미 몸을 더럽혔은즉 그를 내보낸 전남편이 그를 다시 아내로 맞이하지 말지니 이 일은 여호와 앞에 가증한 것이라 너는 네 하나님 여호와께서 네게 기업으로 주시는 땅을 범죄하게 하지 말지니라',5530),
('deu-24-5','deu','신명기',24,5,'사람이 새로이 아내를 맞이하였으면 그를 군대로 내보내지 말 것이요 아무 직무도 그에게 맡기지 말 것이며 그는 일 년 동안 한가하게 집에 있으면서 그가 맞이한 아내를 즐겁게 할지니라',5531),
('deu-24-6','deu','신명기',24,6,'사람이 맷돌이나 그 위짝을 전당 잡지 말지니 이는 그 생명을 전당 잡음이니라',5532),
('deu-24-7','deu','신명기',24,7,'사람이 자기 형제 곧 이스라엘 자손 중 한 사람을 유인하여 종으로 삼거나 판 것이 발견되면 그 유인한 자를 죽일지니 이같이 하여 너희 중에서 악을 제할지니라',5533),
('deu-24-8','deu','신명기',24,8,'너는 나병에 대하여 삼가서 레위 사람 제사장들이 너희에게 가르치는 대로 네가 힘써 다 지켜 행하되 너희는 내가 그들에게 명령한 대로 지켜 행하라',5534),
('deu-24-9','deu','신명기',24,9,'너희는 애굽에서 나오는 길에서 네 하나님 여호와께서 미리암에게 행하신 일을 기억할지니라',5535),
('deu-24-10','deu','신명기',24,10,'네 이웃에게 무엇을 꾸어줄 때에 너는 그의 집에 들어가서 전당물을 취하지 말고',5536),
('deu-24-11','deu','신명기',24,11,'너는 밖에 서 있고 네게 꾸는 자가 전당물을 밖으로 가지고 나와서 네게 줄 것이며',5537),
('deu-24-12','deu','신명기',24,12,'그가 가난한 자이면 너는 그의 전당물을 가지고 자지 말고',5538),
('deu-24-13','deu','신명기',24,13,'해 질 때에 그 전당물을 반드시 그에게 돌려줄 것이라 그리하면 그가 그 옷을 입고 자며 너를 위하여 축복하리니 그 일이 네 하나님 여호와 앞에서 네 공의로움이 되리라',5539),
('deu-24-14','deu','신명기',24,14,'곤궁하고 빈한한 품꾼은 너희 형제든지 네 땅 성문 안에 우거하는 객이든지 그를 학대하지 말며',5540),
('deu-24-15','deu','신명기',24,15,'그 품삯을 당일에 주고 해 진 후까지 미루지 말라 이는 그가 가난하므로 그 품삯을 간절히 바람이라 그가 너를 여호와께 호소하지 않게 하라 그렇지 않으면 그것이 네게 죄가 될 것임이라',5541),
('deu-24-16','deu','신명기',24,16,'아버지는 그 자식들로 말미암아 죽임을 당하지 않을 것이요 자식들은 그 아버지로 말미암아 죽임을 당하지 않을 것이니 각 사람은 자기 죄로 말미암아 죽임을 당할 것이니라',5542),
('deu-24-17','deu','신명기',24,17,'너는 객이나 고아의 송사를 억울하게 하지 말며 과부의 옷을 전당 잡지 말라',5543),
('deu-24-18','deu','신명기',24,18,'너는 애굽에서 종 되었던 일과 네 하나님 여호와께서 너를 거기서 속량하신 것을 기억하라 이러므로 내가 네게 이 일을 행하라 명령하노라',5544),
('deu-24-19','deu','신명기',24,19,'네가 밭에서 곡식을 벨 때에 그 한 뭇을 밭에 잊어버렸거든 다시 가서 가져오지 말고 나그네와 고아와 과부를 위하여 남겨두라 그리하면 네 하나님 여호와께서 네 손으로 하는 모든 일에 복을 내리시리라',5545),
('deu-24-20','deu','신명기',24,20,'네가 네 감람나무를 떤 후에 그 가지를 다시 살피지 말고 그 남은 것은 객과 고아와 과부를 위하여 남겨두며',5546),
('deu-24-21','deu','신명기',24,21,'네가 네 포도원의 포도를 딴 후에 그 남은 것을 다시 따지 말고 객과 고아와 과부를 위하여 남겨두라',5547),
('deu-24-22','deu','신명기',24,22,'너는 애굽 땅에서 종 되었던 것을 기억하라 이러므로 내가 네게 이 일을 행하라 명령하노라',5548),
('deu-25-1','deu','신명기',25,1,'사람들 사이에 시비가 생겨 재판을 청하면 재판장은 그들을 재판하여 의인은 의롭다 하고 악인은 정죄할 것이며',5549),
('deu-25-2','deu','신명기',25,2,'악인에게 태형이 합당하면 재판장은 그를 엎드리게 하고 그 앞에서 그의 죄에 따라 수를 맞추어 때리게 하라',5550),
('deu-25-3','deu','신명기',25,3,'사십까지는 때리려니와 그것을 넘기지는 못할지니 만일 그것을 넘겨 매를 지나치게 때리면 네가 네 형제를 경히 여기는 것이 될까 하노라',5551),
('deu-25-4','deu','신명기',25,4,'곡식 떠는 소에게 망을 씌우지 말지니라',5552),
('deu-25-5','deu','신명기',25,5,'형제들이 함께 사는데 그 중 하나가 죽고 아들이 없거든 그 죽은 자의 아내는 나가서 타인에게 시집 가지 말 것이요 그의 남편의 형제가 그에게로 들어가서 그를 맞이하여 아내로 삼아 그의 남편의 형제 된 의무를 그에게 다 행할 것이요',5553),
('deu-25-6','deu','신명기',25,6,'그 여인이 낳은 첫 아들이 그 죽은 형제의 이름을 잇게 하여 그 이름이 이스라엘 중에서 끊어지지 않게 할 것이니라',5554),
('deu-25-7','deu','신명기',25,7,'그러나 그 사람이 만일 그 형제의 아내 맞이하기를 즐겨하지 아니하면 그 형제의 아내는 그 성문으로 장로들에게로 나아가서 말하기를 내 남편의 형제가 그의 형제의 이름을 이스라엘 중에 잇기를 싫어하여 남편의 형제 된 의무를 내게 행하지 아니하나이다 할 것이요',5555),
('deu-25-8','deu','신명기',25,8,'그 성읍 장로들은 그를 불러다가 말할 것이며 그가 이미 정한 뜻대로 말하기를 내가 그 여자를 맞이하기를 즐겨하지 아니하노라 하면',5556),
('deu-25-9','deu','신명기',25,9,'그의 형제의 아내가 장로들 앞에서 그에게 나아가서 그의 발에서 신을 벗기고 그의 얼굴에 침을 뱉으며 이르기를 그의 형제의 집을 세우기를 즐겨 아니하는 자에게는 이같이 할 것이라 하고',5557),
('deu-25-10','deu','신명기',25,10,'이스라엘 중에서 그의 이름을 신 벗김 받은 자의 집이라 부를 것이니라',5558),
('deu-25-11','deu','신명기',25,11,'두 사람이 서로 싸울 때에 한 사람의 아내가 그 치는 자의 손에서 그의 남편을 구하려 하여 가까이 가서 손을 벌려 그 사람의 음낭을 잡거든',5559),
('deu-25-12','deu','신명기',25,12,'너는 그 여인의 손을 찍어버릴 것이고 네 눈이 그를 불쌍히 여기지 말지니라',5560),
('deu-25-13','deu','신명기',25,13,'너는 네 주머니에 두 종류의 저울추 곧 큰 것과 작은 것을 넣지 말 것이며',5561),
('deu-25-14','deu','신명기',25,14,'네 집에 두 종류의 되 곧 큰 것과 작은 것을 두지 말 것이요',5562),
('deu-25-15','deu','신명기',25,15,'오직 온전하고 공정한 저울추를 두며 온전하고 공정한 되를 둘 것이라 그리하면 네 하나님 여호와께서 네게 주시는 땅에서 네 날이 길리라',5563),
('deu-25-16','deu','신명기',25,16,'이런 일들을 행하는 모든 자, 악을 행하는 모든 자는 네 하나님 여호와께 가증하니라',5564),
('deu-25-17','deu','신명기',25,17,'너희는 애굽에서 나오는 길에 아말렉이 네게 행한 일을 기억하라',5565),
('deu-25-18','deu','신명기',25,18,'곧 그들이 너를 길에서 만나 네가 피곤할 때에 네 뒤에 떨어진 약한 자들을 쳤고 하나님을 두려워하지 아니하였느니라',5566),
